"use strict";(self.webpackChunkmy_personal_website=self.webpackChunkmy_personal_website||[]).push([[1248],{33:e=>{e.exports=JSON.parse('{"permalink":"/blog/bills","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-05-05-bills/index.md","source":"@site/blog/2026-05-05-bills/index.md","title":"Bills","description":"I went to the dentist yesterday. After examining my teeth (X-rays and poking around with that small sickle and mirror), they said they found 3 cavities. 2 that needed to be re-filled (re-filled?! I thought it was a 1 time thing!), and 1 that was new. The total for this procedure came out to be about $700. I just came in for a cleaning, but they wouldn\'t do it without the other things bundled in. They recommended I do a payment plan. Mind you, I\'m paying for a dental plan (This is different from insurance, I\'m not sure how though) to handle most of the costs, so the total is after the discount.","date":"2026-05-05T00:00:00.000Z","tags":[{"inline":true,"label":"Daily Life","permalink":"/blog/tags/daily-life"}],"readingTime":3.52,"hasTruncateMarker":false,"authors":[{"name":"Travis Blanks","title":"Jack of All Trades","url":"https://travisblanks.com","imageURL":"/img/channels4_profile.jpg","key":"Gekaku","page":null}],"frontMatter":{"slug":"bills","title":"Bills","authors":"Gekaku","tags":["Daily Life"]},"unlisted":false,"prevItem":{"title":"Prepping to Leave","permalink":"/blog/prepping-to-leave"},"nextItem":{"title":"My Sister","permalink":"/blog/my-sister"}}')},2638:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>m,frontMatter:()=>s,metadata:()=>n,toc:()=>l});var n=a(33),o=a(4848),i=a(8453);const s={slug:"bills",title:"Bills",authors:"Gekaku",tags:["Daily Life"]},r=void 0,h={authorsImageUrls:[void 0]},l=[];function d(e){const t={a:"a",img:"img",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:"I went to the dentist yesterday. After examining my teeth (X-rays and poking around with that small sickle and mirror), they said they found 3 cavities. 2 that needed to be re-filled (re-filled?! I thought it was a 1 time thing!), and 1 that was new. The total for this procedure came out to be about $700. I just came in for a cleaning, but they wouldn't do it without the other things bundled in. They recommended I do a payment plan. Mind you, I'm paying for a dental plan (This is different from insurance, I'm not sure how though) to handle most of the costs, so the total is after the discount."}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"A photo of my dental costs.",src:a(5177).A+"",width:"4032",height:"2268"})}),"\n",(0,o.jsx)(t.p,{children:"The evaluation they gave me was $87. I can't take this no more. How the heck am I supposed to afford anything? I never thought being an adult would be this hard. It seemed like my parents had everything under control growing up. They never really showed us how insanely expensive literally everything is in comparison to how much money they had. Well, for the most part."}),"\n",(0,o.jsx)(t.p,{children:"I grew up in the suburbs for most of my life. When my parents divorced, my dad moved into some apartments. He later moved into a house, and my mom is currently living in an apartment (Where I'm living right now. I alternate between my dad's house and my mom's apartment). I often wonder why my mom decided to move out of the house she lived in initially. I feel like it's because of a lack of money management. There would be times when the cable would go out for a few weeks, or the times when she would go to a payday loan place on our way home from school. Just yesterday, I asked her about a letter on our door threatening to evict her if she didn't pay the rent in 3 days. She says it was because of a change in payment methods that they were unaware of. I don't believe it."}),"\n",(0,o.jsx)(t.p,{children:"No matter how much I look at it, there's just no way I can keep living with these constant bills looming over me. It just doesn't seem feasible for me to achieve my goals without subtracting a huge portion of the things I'd like to have. My dad told me he had to stop collecting comic books when me and my siblings were born. This is one of the main reasons I don't plan on having a relationship or children. With the insane amount of bills that are thrown my way on the daily, there's just no way I can hope to accomplish anything without getting rid of unnecessary things."}),"\n",(0,o.jsx)(t.p,{children:"Here's an example: The image below is an unpaid debt of mine:"}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"A photo of an unpaid debt.",src:a(3443).A+"",width:"4032",height:"2268"})}),"\n",(0,o.jsxs)(t.p,{children:["When I lost that ",(0,o.jsx)(t.a,{href:"https://blog.gekaku.com/blog/how-life-has-been-going-these-past-few-years",children:"Wells Fargo job"}),", I no longer had a way to pay off my credit card bills. This, along with another credit card adds up to about $15,000 in debt. If you add my student loans to the picture, that's about $45,000 of debt. Luckily, I'm not paying any student loans right now because I was able to get them deferred for a year. I might have to pay them later on this year if I'm unable to do that again. Before that happens, I gotta find me a job."]}),"\n",(0,o.jsxs)(t.p,{children:["Mark my words, I'm not gonna make this money mistake again. As soon as these debts are paid off, I'm gonna start saving up. This is gonna be much easier to do now that I'm living with my parents again. But don't get it twisted, I will still be traveling to track meets and tournaments to compete. That's what I've prepared my ",(0,o.jsx)(t.a,{href:"https://blog.gekaku.com/blog/My-Car",children:"car"})," for."]}),"\n",(0,o.jsx)(t.p,{children:"My tax return came in, so I've got about $900 to spare at the moment. I've just been eating whatever my parents have in the kitchen, and restricting my driving to only going to my dad's house or sister's temporary apartment. Once I get a job, I'll start planning other travel ventures."})]})}function m(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},3443:(e,t,a)=>{a.d(t,{A:()=>n});const n=a.p+"assets/images/20260505_200935-692612234b697cf9c3c9359b7360dc2d.jpg"},5177:(e,t,a)=>{a.d(t,{A:()=>n});const n=a.p+"assets/images/20260505_201035-993111f2c856c40b4357459e53d24b88.jpg"},8453:(e,t,a)=>{a.d(t,{R:()=>s,x:()=>r});var n=a(6540);const o={},i=n.createContext(o);function s(e){const t=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);